  implicit def tuple4ToAnyValue[A1, A2, A3, A4](implicit a1: ToAnyValue[A1], a2: ToAnyValue[A2], a3: ToAnyValue[A3], a4: ToAnyValue[A4]): ToAnyValue[Tuple4[A1, A2, A3, A4]] =
